trait Reverse {
    fn reverse(self) -> Self;
}

impl Reverse for u32 {
    fn reverse(self) -> Self {
        let mut result = 0;
        let mut n = self;
        while n > 0 {
            result = result * 10 + n % 10;
            n /= 10;
        }
        result
    }
}

